function Icon({as:I,size=20,color=C.ink,...rest}){return <I size={size} color={color} strokeWidth={1.7} {...rest}/>}
function Txt({children,style,...props}){return <Text style={[s.text,style]} {...props}>{children}</Text>}
function Button({children,onPress,secondary=false,icon:I,style}){return <Pressable onPress={onPress} style={({pressed})=>[s.button,secondary&&s.secondary,pressed&&{opacity:.7},style]}>{I&&<Icon as={I} size={17} color={secondary?C.ink:'white'}/>}<Txt style={{color:secondary?C.ink:'white',fontSize:13,fontWeight:'600'}}>{children}</Txt></Pressable>}
function Avatar({person=defaultProfile,size=40}){return <View style={{width:size,height:size,borderRadius:size/2,backgroundColor:person.color,alignItems:'center',justifyContent:'center',borderWidth:2,borderColor:'#ffffffee'}}>{person.avatar?<Image source={{uri:person.avatar}} style={{width:'100%',height:'100%',borderRadius:size/2}}/>:<Txt style={{fontFamily:Platform.OS==='web'?'Georgia':undefined,fontSize:size*.43,color:'#503d32'}}>{person.initial}</Txt>}</View>}
function Glass({children,style,frosted=false}){return <GlassSurface frosted={frosted} style={style}>{children}</GlassSurface>}
function PostCard({post,onPress,onLike,liked=false,fill=false}){const ref=useRef(null);return <Pressable ref={ref} accessibilityLabel={onPress?`Open thread: ${post.title}`:undefined} onPress={onPress?()=>ref.current?.measureInWindow((x,y,width,height)=>onPress({x,y,width,height})):undefined} style={{height:fill?'100%':244}}><Glass style={[s.feedCard,{flex:1}]}><View style={[s.row,{justifyContent:'space-between'}]}><View style={s.row}><Avatar person={post.person} size={32}/><Txt style={{fontSize:12,fontWeight:'600'}}>@{post.person.handle}</Txt><Txt style={{fontSize:11,color:C.muted}}>{post.time}</Txt></View></View><Txt style={{fontSize:26,letterSpacing:-.7,marginTop:19}}>{post.title}</Txt>{!!post.body&&<Txt style={{fontSize:14,lineHeight:22,marginTop:10}}>{post.body}</Txt>}<View style={[s.row,{gap:18,marginTop:'auto',paddingTop:14}]}><Pressable accessibilityRole="button" accessibilityLabel={liked?'Unlike post':'Like post'} accessibilityState={{selected:liked}} hitSlop={9} onPress={event=>{event.stopPropagation();onLike?.()}} style={[s.row,{paddingVertical:5,paddingRight:5}]}><Heart size={16} color={liked?C.coral:C.muted} fill={liked?C.coral:'transparent'}/><Txt style={{fontSize:11,color:liked?C.coral:C.muted}}>{post.likes||0}</Txt></Pressable><View style={s.row}><MessageCircle size={16} color={C.muted}/><Txt style={{fontSize:11,color:C.muted}}>{post.count||0}</Txt></View></View></Glass></Pressable>}
function ClubTile({club,onPress}){const ref=useRef(null);return <Pressable ref={ref} accessibilityLabel={`Open ${club.name}`} onPress={()=>ref.current?.measureInWindow((x,y,width,height)=>onPress({x,y,width,height}))} style={[s.clubTile,{backgroundColor:club.color}]}><Icon as={club.Icon} size={30}/><Txt style={{fontSize:12,fontWeight:'600',marginTop:18}}>{club.name}</Txt><Txt style={{fontSize:9,color:'#8a8d7d',marginTop:4}}>{club.members}</Txt></Pressable>}
function ClubBanner({club}){return <View style={s.clubBanner}><Image source={{uri:club.name==='Design club'?photos.library:club.name==='Trail collective'?photos.garden:photos.palm}} style={StyleSheet.absoluteFillObject}/><LinearGradient colors={['#142e2a10','#142e2a25','#142e2aeb']} style={StyleSheet.absoluteFillObject}/><View style={s.clubBannerIdentity}><Glass style={s.clubBannerIcon}><Icon as={club.Icon} size={34} color="white"/></Glass><View style={{flex:1}}><Txt style={{fontSize:25,color:'white',letterSpacing:-.7}}>{club.name}</Txt><Txt style={{fontSize:11,color:'#e5eadf',marginTop:7}}>{club.members}</Txt></View></View></View>}
