function useBrowserInsets(enabled){
 const [insets,setInsets]=useState({top:0,bottom:0});
 useEffect(()=>{
  if(!enabled||Platform.OS!=='web'||typeof document==='undefined'||typeof window==='undefined')return;
  const probe=document.createElement('div');
  probe.style.cssText='position:fixed;left:0;top:0;padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom);visibility:hidden;pointer-events:none';
  document.body.appendChild(probe);
  const read=()=>{
   const style=getComputedStyle(probe);
   setInsets({top:parseFloat(style.paddingTop)||0,bottom:parseFloat(style.paddingBottom)||0});
  };
  read();
  window.addEventListener('resize',read);
  window.addEventListener('orientationchange',read);
  window.visualViewport?.addEventListener('resize',read);
  window.visualViewport?.addEventListener('scroll',read);
  return()=>{
   probe.remove();
   window.removeEventListener('resize',read);
   window.removeEventListener('orientationchange',read);
   window.visualViewport?.removeEventListener('resize',read);
   window.visualViewport?.removeEventListener('scroll',read);
  };
 },[enabled]);
 return insets;
}
